extern crate indoc;
extern crate liwe;

use indoc::indoc;
use liwe::find::{DocumentFinder, FindOptions};
use liwe::graph::Graph;
use liwe::model::config::MarkdownOptions;
use liwe::state::from_indoc;

fn main() {
    for input in [
        indoc! {"
            title: Task A
            depends:
              - foo

            # Task A
        "},
        indoc! {"
            title: Task A
            depends:
            - foo

            # Task A
        "},
    ] {
        let graph = Graph::import(
            &from_indoc(input),
            MarkdownOptions { bare_frontmatter: true, ..Default::default() },
            None,
        );
        println!("input:\n{input:?}");
        println!("meta: {:?}", graph.get_metadata(&"1".into()));
        let out = DocumentFinder::new(&graph).find(&FindOptions {
            metadata_filters: vec![("depends".to_string(), "foo".to_string())],
            ..Default::default()
        });
        println!("results: {}\n", out.results.len());
    }
}
EOF
